package com.guocheng.mediapocket;
import org.json.*;import java.net.*;
public class EmbyApiTest {
 static void check(boolean ok,String m){if(!ok)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{
  String bare=EmbyApi.authorization("And\"roid","dev,1","0.1.72","");
  check(bare.equals("MediaBrowser Client=\"MediaPocket\", Device=\"Android\", DeviceId=\"dev1\", Version=\"0.1.72\""),"auth header without token");
  check(!bare.contains("Token=")&&!bare.contains("\n")&&!bare.contains("\""+"\r"),"header stays one line");
  String authed=EmbyApi.authorization("Android","dev-1",null,"abc");
  check(authed.endsWith(", Token=\"abc\"")&&authed.contains("Version=\"0.1.72\""),"token appended and default version");
  check(EmbyApi.server("http://192.168.1.8:8096/").equals("http://192.168.1.8:8096"),"port kept, slash trimmed");
  check(EmbyApi.server("https://media.example:8920/emby/").equals("https://media.example:8920/emby"),"https path prefix kept");
  check(EmbyApi.server("https://media.example/emby/").equals("https://media.example/emby"),"https host without port");
  check(EmbyApi.server("http://192.168.1.10/").equals("http://192.168.1.10"),"http host without port");
  check(EmbyApi.port(new URI(EmbyApi.server("https://media.example")))==443,"omitted https port is 443");
  check(EmbyApi.port(new URI(EmbyApi.server("http://192.168.1.10")))==80,"omitted http port is 80");
  check(EmbyApi.sameServer("https://media.example","https://media.example:443")&&EmbyApi.sameServer("http://192.168.1.10","http://192.168.1.10:80"),"default ports match an omitted port");
  check(!EmbyApi.sameServer("https://media.example","https://media.example:8920"),"explicit non-default port stays different");
  check(EmbyApi.serverHint().contains("端口可省略"),"url hint says the port may be omitted");
  check(EmbyApi.authenticateUrl("http://10.0.0.2:8096").equals("http://10.0.0.2:8096/Users/AuthenticateByName"),"authenticate path");
  check(EmbyApi.authenticateUrl("https://media.example").equals("https://media.example/Users/AuthenticateByName"),"authenticate without port");
  JSONObject body=EmbyApi.authenticateBody("ada","p@ss");check(body.getString("Username").equals("ada")&&body.getString("Pw").equals("p@ss")&&body.getString("Password").equals("p@ss"),"Pw and Password");
  JSONObject blank=EmbyApi.authenticateBody("guest","");check(blank.getString("Pw").equals("")&&blank.getString("Password").equals("")&&blank.toString().contains("\"Pw\":\"\""),"empty password sends Pw");
  check(EmbyApi.authenticateBody("guest",null).getString("Pw").equals(""),"null password sends empty Pw");
  check("".equals(EmbyApi.loginPassword(false,"","saved"))&&"next".equals(EmbyApi.loginPassword(false,"next","saved")),"adding keeps an empty password");
  check("saved".equals(EmbyApi.loginPassword(true,"","saved"))&&"next".equals(EmbyApi.loginPassword(true,"next","saved")),"editing blank keeps the saved password");
  check("密码（没有可留空）".equals(EmbyApi.passwordHint(false))&&"密码（留空则不修改）".equals(EmbyApi.passwordHint(true)),"password placeholders");
  for(String bad:new String[]{"ftp://host/a","http://user:pw@host:8096","notaurl","http://","  "}){boolean rejected=false;try{EmbyApi.server(bad);}catch(IllegalArgumentException e){rejected=e.getMessage()!=null&&(e.getMessage().contains("http")||e.getMessage().contains("地址")||e.getMessage().contains("账号")||e.getMessage().contains("填写"));}check(rejected,"rejected "+bad);}
  String image=EmbyApi.imageUrl("http://h:8096","item 1","Primary","tok en",400,"tag/1");
  check(image.startsWith("http://h:8096/Items/")&&image.contains("/Images/Primary")&&image.contains("api_key=")&&image.contains("tag="),"image url");
  check(EmbyApi.msToTicks(1000)==10000000L&&EmbyApi.ticksToMs(10000000L)==1000L,"tick second");
  check(EmbyApi.msToTicks(0)==0&&EmbyApi.msToTicks(-5)==0&&EmbyApi.ticksToMs(-1)==0,"tick non-positive");
  check(EmbyApi.msToTicks(Long.MAX_VALUE)==Long.MAX_VALUE,"tick saturates");
  check(EmbyApi.ticksToMs(EmbyApi.msToTicks(123456))==123456L,"tick round trip");
  JSONObject direct=source("file-1",true,false,null,null);
  JSONObject trans=source("file-2",false,false,"/videos/abc/master.m3u8?id=1",null);
  JSONObject info=new JSONObject().put("PlaySessionId","play1").put("MediaSources",new JSONArray().put(trans).put(direct));
  EmbyApi.Choice chosen=EmbyApi.select("http://10.0.0.8:8096","item", "tok", info);
  check(chosen.direct&&chosen.url.contains("static=true")&&chosen.url.contains("MediaSourceId=file-1")&&chosen.url.contains("api_key=tok")&&chosen.url.contains("PlaySessionId=play1"),"direct static wins over earlier transcode");
  check(!chosen.url.contains("master.m3u8"),"transcode url not chosen");
  EmbyApi.Choice fallback=EmbyApi.select("http://10.0.0.8:8096","abc","tok",new JSONObject().put("PlaySessionId","p").put("MediaSources",new JSONArray().put(trans)));
  check(!fallback.direct&&fallback.url.equals("http://10.0.0.8:8096/videos/abc/master.m3u8?id=1&api_key=tok"),"transcode fallback absolute");
  JSONObject given=source("ms",true,true,null,"http://h:8096/videos/abc/stream.mkv?static=true");
  EmbyApi.Choice kept=EmbyApi.select("http://h:8096","abc","secret",new JSONObject().put("PlaySessionId","s").put("MediaSources",new JSONArray().put(given)));
  check(kept.direct&&kept.url.startsWith("http://h:8096/videos/abc/stream.mkv?static=true")&&kept.url.contains("api_key=secret"),"existing static url kept");
  check(kept.subtitles.length()==2&&kept.subtitles.getJSONObject(0).getString("name").contains("外挂")&&kept.subtitles.getJSONObject(1).getString("name").contains("内嵌"),"external and embedded subtitles");
  check(kept.subtitles.getJSONObject(0).getString("url").contains("api_key=secret")&&kept.subtitles.getJSONObject(1).getString("url").contains("/Subtitles/3/"),"subtitle urls");
  check(kept.audio.length()==1&&kept.audio.getJSONObject(0).getString("label").contains("6声道"),"audio track label");
  JSONObject session=EmbyApi.sessionBody("item","ms","s",EmbyApi.msToTicks(1500),false,true);
  check(session.getString("PlayMethod").equals("DirectStream")&&session.getLong("PositionTicks")==15000000L,"playing body ticks");
  check(EmbyApi.sessionBody("item","ms","s",0,true,false).getString("PlayMethod").equals("Transcode"),"transcode method");
  long second=10000000L;check(EmbyApi.played(900*second,1000*second)&&!EmbyApi.played(800*second,1000*second),"ninety percent");
  check(EmbyApi.played(80*second,100*second),"tail under 30s counts as played");
  check(!EmbyApi.played(0,1000*second)&&!EmbyApi.played(10,0),"no false played");
  check(EmbyApi.explain(new SocketTimeoutException("slow")).contains("超时"),"timeout message");
  check(EmbyApi.explain(new UnknownHostException("nope")).contains("找不到"),"dns message");
  check(EmbyApi.explain(new java.net.ConnectException("refused")).contains("无法连接"),"connect message");
  check(EmbyApi.explain(new java.io.IOException("HTTP 401")).equals("用户名或密码不正确"),"password message stays exact");
  check(!EmbyApi.explain(new java.io.IOException("HTTP 401")).contains("客户端"),"401 is not a client refusal");
  String refused="请使用群公告中允许的客户端进行访问";
  EmbyApi.AuthAttempt once=EmbyApi.authAttempt("MediaPocket",403,refused+" ",false);
  check(once.retry&&"Emby".equals(once.client)&&once.error==null,"MediaPocket rejection retries once as Emby");
  EmbyApi.AuthAttempt again=EmbyApi.authAttempt(once.client,403,refused,true);
  check(!again.retry&&EmbyApi.explain(new java.io.IOException(again.error)).equals(refused),"second refusal shows the server text");
  EmbyApi.AuthAttempt already=EmbyApi.authAttempt("Emby",403,refused,false);
  check(!already.retry&&EmbyApi.explain(new java.io.IOException(already.error)).equals(refused),"official name is not retried again");
  EmbyApi.AuthAttempt hills=EmbyApi.authAttempt("Infuse",403,refused,false);
  check(hills.retry&&"Emby".equals(hills.client)&&!"Hills".equals(hills.client),"fallback is Emby, not a third-party name");
  EmbyApi.AuthAttempt bad=EmbyApi.authAttempt("MediaPocket",401,"用户名或密码无效。请重试。 secret-password",false);
  check(!bad.retry&&"HTTP 401".equals(bad.error)&&!bad.error.contains("secret-password")&&EmbyApi.explain(new java.io.IOException(bad.error)).equals("用户名或密码不正确"),"401 does not retry and does not carry the password");
  EmbyApi.AuthAttempt after=EmbyApi.authAttempt("Emby",401,"用户名或密码无效。请重试。",true);
  check(!after.retry&&"HTTP 401".equals(after.error),"fallback that gets a real 401 stays the password error");
  EmbyApi.AuthAttempt json=EmbyApi.authAttempt("MediaPocket",403,"{\"Message\":\"Access denied.\"}",false);
  check(!json.retry&&"HTTP 403".equals(json.error),"json 403 is not a client-name retry");
  EmbyApi.AuthAttempt emptyBody=EmbyApi.authAttempt("MediaPocket",403,"  ",false);
  check(!emptyBody.retry&&"HTTP 403".equals(emptyBody.error),"blank 403 is not a client-name retry");
  EmbyApi.AuthAttempt accepted=EmbyApi.authAttempt("MediaPocket",200,"{\"AccessToken\":\"abcdef0123456789abcdef0123456789\"}",false);
  check(!accepted.retry&&"MediaPocket".equals(accepted.client)&&accepted.error==null,"accepted MediaPocket is unchanged and the token is not kept on the plan");
  check("服务器不允许这个客户端".equals(EmbyApi.clientNotice(""))&&"服务器不允许这个客户端".equals(EmbyApi.clientNotice("<html>client blocked</html>")),"unreadable refusal uses the short message");
  String redacted=EmbyApi.clientNotice(refused+" abcdef0123456789abcdef0123456789");
  check(redacted.startsWith(refused)&&!redacted.contains("abcdef0123456789"),"client notice drops a token-like hex string");
  check(EmbyApi.explain(new java.io.IOException("HTTP 403")).contains("拒绝访问"),"other 403 stays the permission message");
  String embyHeader=EmbyApi.authorization("Emby","Android","dev","0.1.72","");
  check(embyHeader.contains("Client=\"Emby\"")&&!embyHeader.contains("MediaPocket")&&!embyHeader.contains("Hills")&&!embyHeader.contains("Token="),"official header has no token");
  check(EmbyApi.authorization("MediaPocket","Android","dev","0.1.72","").contains("Client=\"MediaPocket\""),"MediaPocket header unchanged");
  check("MediaPocket".equals(EmbyApi.clientOf(new JSONObject()))&&"Emby".equals(EmbyApi.clientOf(new JSONObject().put("client","Emby"))),"saved client name");
  check(EmbyApi.explain(new IllegalArgumentException(messageOf("ftp://x"))).contains("http"),"bad scheme message");
  String[] applied=HomeRules.apply("provider:emby:srv-1");check(applied[0].equals("emby")&&applied[1].equals("srv-1"),"emby source id");
  check(HomeRules.apply("provider:fusion")[0].equals("fusion")&&HomeRules.selectedId("stremio","current").equals("provider:stremio"),"existing providers unchanged");
  check(HomeRules.selectedId("emby","srv-1").equals("provider:emby:srv-1"),"selected emby");
  check(EmbyApi.isEmbyId("emby:srv:item")&&EmbyApi.itemOf("emby:srv:item").equals("item")&&EmbyApi.serverOf("emby:srv:item").equals("srv"),"watch id");
  JSONObject strm=new JSONObject().put("Id","ms9").put("SupportsDirectStream",true).put("Path","https://cdn.other.example/a.mkv?sig=1").put("MediaStreams",new JSONArray().put(new JSONObject().put("Index",4).put("Type","Subtitle").put("IsExternal",true).put("DeliveryUrl","https://subs.other.example/x.srt")));
  EmbyApi.Choice remote=EmbyApi.select("http://h:8096","it9","secret",new JSONObject().put("PlaySessionId","p9").put("MediaSources",new JSONArray().put(strm)));
  check(remote.url.startsWith("http://h:8096/Videos/it9/stream?static=true")&&remote.url.contains("api_key=secret"),"remote .strm path goes through the server stream endpoint: "+remote.url);
  check(remote.subtitles.getJSONObject(0).getString("url").equals("https://subs.other.example/x.srt"),"external-host subtitle gets no api_key");
  check(!EmbyApi.keyed("http://h:8096","http://h:9000/x","t").contains("api_key")&&EmbyApi.keyed("http://h:8096","http://H:8096/x","t").contains("api_key=t"),"api_key only for same host and port");
  JSONObject st=EmbyApi.stream(new JSONObject().put("token","secret").put("id","s"),"it9",remote,0);
  check(st.getJSONObject("behaviorHints").getJSONObject("proxyHeaders").getJSONObject("request").length()==0,"token not sent as header (would follow redirects to other hosts)");
  check(!remote.url.contains("X-Emby-Client"),"MediaPocket stream url stays unchanged");
  EmbyApi.Choice named=EmbyApi.select("http://h:8096","it9","secret",new JSONObject().put("PlaySessionId","p9").put("MediaSources",new JSONArray().put(strm)),null,EmbyApi.OFFICIAL_CLIENT);
  check(named.url.contains("static=true")&&named.url.contains("api_key=secret")&&named.url.contains("X-Emby-Client=Emby")&&!named.url.contains("Token="),"official client is a query on the stream, token stays api_key");
  check(named.subtitles.getJSONObject(0).getString("url").equals("https://subs.other.example/x.srt"),"other-host subtitle does not get the client query");
  EmbyApi.Choice namedLocal=EmbyApi.select("http://h:8096","abc","secret",new JSONObject().put("PlaySessionId","s").put("MediaSources",new JSONArray().put(given)),null,EmbyApi.OFFICIAL_CLIENT);
  check(namedLocal.subtitles.getJSONObject(0).getString("url").contains("X-Emby-Client=Emby")&&namedLocal.subtitles.getJSONObject(0).getString("url").contains("api_key=secret"),"same-server subtitle names Emby");
  JSONObject namedStream=EmbyApi.stream(new JSONObject().put("token","secret").put("id","s").put("client","Emby"),"it9",named,0);
  check(namedStream.getJSONObject("behaviorHints").getJSONObject("proxyHeaders").getJSONObject("request").length()==0&&!namedStream.getJSONObject("behaviorHints").toString().contains("secret"),"fallback still does not put the token in a header");
  check(EmbyApi.playbackInfoBody("u",EmbyApi.msToTicks(600000)).getLong("StartTimeTicks")==0L,"transcode not pre-shifted; player seeks to resume");
  System.out.println("PASS: Emby auth header, server URL, ticks, PlaybackInfo direct-or-transcode selection, subtitles and audio.");
 }
 static String messageOf(String url){try{EmbyApi.server(url);return "";}catch(IllegalArgumentException e){return e.getMessage();}}
 static JSONObject source(String id,boolean direct,boolean play,String trans,String directUrl)throws Exception{
  JSONObject s=new JSONObject().put("Id",id).put("SupportsDirectStream",direct).put("SupportsDirectPlay",play);
  if(trans!=null)s.put("TranscodingUrl",trans);if(directUrl!=null)s.put("DirectStreamUrl",directUrl);
  JSONArray streams=new JSONArray();
  streams.put(new JSONObject().put("Index",1).put("Type","Audio").put("DisplayTitle","国语").put("Language","chi").put("Channels",6).put("Codec","aac"));
  streams.put(new JSONObject().put("Index",2).put("Type","Subtitle").put("DisplayTitle","简体").put("Language","chi").put("IsExternal",true).put("DeliveryMethod","External").put("DeliveryUrl","/Videos/abc/ms/Subtitles/2/Stream.srt"));
  streams.put(new JSONObject().put("Index",3).put("Type","Subtitle").put("DisplayTitle","繁体").put("Language","chi").put("IsExternal",false).put("DeliveryMethod","Embed").put("Codec","ass"));
  return s.put("MediaStreams",streams);
 }
}
